import {today,completeness} from './core.js';
export const educationLevels=['ประถมศึกษา','มัธยมศึกษาตอนต้น','มัธยมศึกษาตอนปลาย / ปวช.','ปวส. / อนุปริญญา','ปริญญาตรี','ประกาศนียบัตรบัณฑิต','ปริญญาโท','ประกาศนียบัตรบัณฑิตชั้นสูง','ปริญญาเอก','อื่น ๆ'];
export const certKinds={administrator:'ใบประกอบวิชาชีพผู้บริหาร',vocational:'ใบรับรองทักษะวิชาชีพ',teacher_license:'ใบประกอบวิชาชีพครู'};
export const certStates={active:'ยังไม่ถึงกำหนดต่ออายุ',expiring:'ใกล้หมดอายุ',expired:'หมดอายุ',undated:'ไม่ระบุวันหมดอายุ'};
export function certificateState(c,days=90,asof=today()){if(!c.expires_on)return 'undated';if(c.expires_on<asof)return 'expired';const cutoff=new Date(asof+'T00:00:00Z');cutoff.setUTCDate(cutoff.getUTCDate()+Number(days));return c.expires_on<=cutoff.toISOString().slice(0,10)?'expiring':'active';}
export function matchesCertificate(c,p,f={},days=90,asof=today()){if(!p)return false;if(f.school&&String(p.school_id)!==String(f.school))return false;if(f.kind&&c.kind!==f.kind)return false;if(f.issuer&&c.issuer!==f.issuer)return false;if(f.status&&certificateState(c,days,asof)!==f.status)return false;const q=(f.q||'').trim().toLocaleLowerCase('th');return !q||[p.full_name,p.employee_code,c.name,c.issuer,c.number].join(' ').toLocaleLowerCase('th').includes(q);}
export function parseRoute(hash){const [page='dashboard',query='']=hash.replace(/^#/,'').split('?');const params=new URLSearchParams(query);return {page:page||'dashboard',filters:Object.fromEntries(['q','school','status','education','issuer','kind','readiness'].map(k=>[k,params.get(k)||'']))};}
export function routeHref(page,filters={}){const p=new URLSearchParams(Object.entries(filters).filter(([,v])=>v!==undefined&&v!==null&&v!==''));return '#'+page+(p.size?'?'+p.toString():'');}
export function getOverview(data,days=90,asof=today()){const personnel=(data.personnel||[]).filter(p=>!p.deleted_at),ids=new Set(personnel.map(p=>p.id)),certificates=(data.certificates||[]).filter(c=>ids.has(c.personnel_id)),documents=(data.documents||[]).filter(d=>ids.has(d.personnel_id)),{document_types=[],schools=[]}=data;const scores=personnel.map(p=>({p,...completeness(p,documents,document_types)}));return {expiryDays:days,degrees:[...new Set(personnel.map(p=>p.highest_education?.trim()||''))].map(degree=>({name:degree||'ยังไม่ระบุวุฒิ',value:degree||'missing',count:personnel.filter(p=>(p.highest_education?.trim()||'')===degree).length})).sort((a,b)=>b.count-a.count),issuers:[...new Set(certificates.map(c=>c.issuer||''))].map(issuer=>({issuer,count:certificates.filter(c=>(c.issuer||'')===issuer).length})).sort((a,b)=>b.count-a.count),total:personnel.length,certificates:certificates.length,holders:new Set(certificates.map(c=>c.personnel_id)).size,schools:schools.map(s=>({...s,count:personnel.filter(p=>p.school_id===s.id).length})),expiring:certificates.filter(c=>certificateState(c,days,asof)==='expiring').length,expired:certificates.filter(c=>certificateState(c,days,asof)==='expired').length,pending:documents.filter(d=>d.status==='pending').length,missingEducation:personnel.filter(p=>!p.highest_education?.trim()).length,incomplete:scores.filter(s=>s.done<s.total).length,required:scores.reduce((a,s)=>a+s.total,0),done:scores.reduce((a,s)=>a+s.done,0)};}
export function validateCertificate(c){if(!c.name?.trim()||!c.issuer?.trim())throw Error('กรุณาระบุชื่อใบรับรองและหน่วยงานผู้ออก');if(!certKinds[c.kind])throw Error('ประเภทใบรับรองไม่ถูกต้อง');for(const k of ['name','issuer','number'])if(String(c[k]||'').length>300)throw Error('ข้อมูลใบรับรองยาวเกินกำหนด');for(const k of ['issued_on','expires_on'])if(c[k]&&(!/^\d{4}-\d{2}-\d{2}$/.test(c[k])||isNaN(Date.parse(c[k]))||new Date(c[k]).toISOString().slice(0,10)!==c[k]))throw Error('วันที่ใบรับรองไม่ถูกต้อง');if(c.issued_on&&c.expires_on&&c.expires_on<c.issued_on)throw Error('วันหมดอายุต้องไม่ก่อนวันออก');return c;}
